create table import_batches (batch_id uuid primary key default gen_random_uuid(),source_agent text not null,file_name text not null,uploaded_by uuid references users(user_id),upload_date timestamptz not null default now(),total_rows integer not null default 0,valid_rows integer not null default 0,error_rows integer not null default 0,status text not null default 'Staged' check(status in('Staged','Validated','Imported','Failed')));
create table shipping_staging_rows (id uuid primary key default gen_random_uuid(),batch_id uuid not null references import_batches(batch_id) on delete cascade,row_number integer not null,raw_row_data jsonb not null,validation_status text not null default 'Pending' check(validation_status in('Pending','Valid','Error','Collapsed')),error_reason text,unique(batch_id,row_number));
create table shipping_master (id uuid primary key default gen_random_uuid(),shipper_inv_no text not null unique,sr_no text,booking_ref_no text,shipper text,consignee text,shipper_inv_date date,pol text,pod text,pol_port_id uuid references ports(port_id),pod_port_id uuid references ports(port_id),product text,planned_vessel_line text,etd date,eta date,fpod text,container_no text,shipping_bill_no text,hbl_no text,mbl_no text,usd_inr_rate_freight numeric(16,4),sea_freight_inv_no text,sea_freight_inv_date date,sea_freight_inv_amount numeric(16,2),other_local_inv_no text,other_local_inv_date date,other_local_inv_amount numeric(16,2),duty_inv_no text,duty_inv_date date,duty_inv_amount numeric(16,2),usd_inr_rate_duty numeric(16,4),updated_at timestamptz not null default now());
create index shipping_master_invoice_date_idx on shipping_master(shipper_inv_date);create index shipping_master_eta_idx on shipping_master(eta);create index shipping_master_search_idx on shipping_master(shipper_inv_no,shipping_bill_no,hbl_no,mbl_no,container_no);

